[Form]
public class AVASalesParameters extends FormRun
{
    NumberSeqReference                      numberSeqReference;
    boolean                                 runExecuteDirect;
    TmpIdRef                                tmpIdRef;
    NumberSeqScope                          scope;
    NumberSeqApplicationModule              numberSeqApplicationModule;
    container                               numberSequenceModules;

    #define.dataAreaId_NDX("NDX")


}

/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    new AVANumberSeqNiedaxSalesModule().load();

    this.numberSeqPreInit();

    super();

    AVASalesParameters.ModuleType = MarkupModuleType::Cust;

    if(strUpr(curExt()) == #dataAreaId_NDX)
    {
        GeneralGrp_ForceSecondaryRequest.enabled(true);
    }
}

/// <summary>
///     AVA <c>numberSeqPreInit</c> method.
/// </summary>
void numberSeqPreInit()
{
    runExecuteDirect            = false;
    numberSequenceModules       = [NumberSeqModule::AVANiedaxSales];
    numberSeqApplicationModule  = new AVANumberSeqNiedaxSalesModule();
    scope = NumberSeqScopeFactory::createDataAreaScope();
    NumberSeqApplicationModule::createReferencesMulti(numberSequenceModules, scope);
    tmpIdRef.setTmpData(NumberSequenceReference::configurationKeyTableMulti(numberSequenceModules));
}

    /// <summary>
    ///     AVA <c>lookupMarkupCode</c> method.
    /// </summary>
    /// <param name="ctrl">
    ///     <c>FormStringControl</c> as type
    /// </param>
    public void lookupMarkupCode(FormStringControl ctrl)
    {
        SysTableLookup          sysTableLookup;
        Query                   query;
        QueryBuildDataSource    queryBuildDataSource;
        QueryBuildRange         queryBuildRange;

        FormDataSource          AVASalesParametersDS;

        AVASalesParametersDS    = element.AVASalesParameters_DS;
        //AVASalesParameters_DS.cursor().ModuleType = ModuleInventCustVend::Cust;
//        locAVASalesParameters =  AVASalesParameters; AVASalesParameters_DS.cursor();
        AVASalesParameters.ModuleType = MarkupModuleType::Cust;


        sysTableLookup          = SysTableLookup::newParameters(tableNum(MarkupTable), ctrl, true);
        query                   = new Query();
        queryBuildDataSource    = query.addDataSource(tableNum(MarkupTable));
        queryBuildRange         = queryBuildDataSource.addRange(fieldNum(MarkupTable, ModuleType));

        //queryBuildRange.value(SysQuery::value(ModuleInventCustVend::Cust));
        queryBuildRange.value(SysQuery::value(AVASalesParameters.ModuleType));

        sysTableLookup.addLookupfield(fieldNum(MarkupTable, MarkupCode));
        sysTableLookup.addLookupfield(fieldNum(MarkupTable, ModuleType));
        sysTableLookup.addLookupfield(fieldNum(MarkupTable, Txt));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_formControl">_formControl</param>
/// <param name = "_filterStr">_filterStr</param>
public void lookup(FormControl _formControl, str _filterStr)
{
    //super(_formControl, _filterStr);
    AVASalesParameters::salesQuotExcelReportLookup(_formControl);
}

/// <summary>
///     AVA <c>removeFilter</c> method.
/// </summary>
void removeFilter()
{
    runExecuteDirect = false;
    numbersequenceReference_ds.executeQuery();
}

/// <summary>
///     AVA <c>executeQuery</c> method.
/// </summary>
void executeQuery()
{
    if (runExecuteDirect)
    {
        super();
    }
    else
    {
        runExecuteDirect = true;
        this.queryRun(NumberSeqReference::buildQueryRunMulti(numberSequenceReference,
                                                             tmpIdRef,
                                                             numberSequenceTable,
                                                             numberSequenceModules,
                                                             scope));
        numbersequenceReference_ds.research();
    }
}

/// <summary>
///   designed from AVA
/// </summary>
/// <param name = "_formReferenceControl">_formReferenceControl</param>
/// <returns>Common</returns>
public Common resolveReference(FormReferenceControl _formReferenceControl)
{
    NumberSequenceCode code = _formReferenceControl.filterValue(
        AbsoluteFieldBinding::construct(fieldStr(NumberSequenceTable, NumberSequence),
        tableStr(NumberSequenceTable))).value();


    return NumberSequenceTable::findByNaturalKey(code, scope.getId(true));
}

/// <summary>
  /// designed from AVA
  /// </summary>
/// <param name = "_formReferenceControl">_formReferenceControl</param>
  /// <returns>commom</returns>
public Common lookupReference(FormReferenceControl _formReferenceControl)
{
    NumberSequenceTable     selectedRecord;
    SysReferenceTableLookup sysTableLookup = SysReferenceTableLookup::newParameters(tableNum(NumberSequenceTable), _formReferenceControl, true);
    Query lookupQuery;

    // Do not call super as we're providing our own custom lookup logic.
    // selectedRecord = super(_formReferenceControl);

    // Display the Title and Department fields in the lookup form.
    sysTableLookup.addLookupfield(fieldNum(NumberSequenceTable, NumberSequence));

    // Create a custom Query that filters on NumberSequenceScope.
    lookupQuery = new Query();
    lookupQuery.addDataSource(tableNum(NumberSequenceTable)).addRange(fieldNum(NumberSequenceTable, NumberSequenceScope)).value(queryValue(scope.getId(true)));
    sysTableLookup.parmQuery(lookupQuery);

    // Return the record selected by the user.
    selectedRecord = sysTableLookup.performFormLookup();

    return selectedRecord;
}

